{!REQUIRESCRIPT("/soap/ajax/52.0/connection.js")} // Include the Salesforce AJAX Toolkit

var vtrmRecordId = '{!Vendor_Trade_Rate_Management__c.Id}'; // Get the record ID
var vtrmRecord = new sforce.SObject("Vendor_Trade_Rate_Management__c"); // Create a new SObject for VTRM
vtrmRecord.Id = vtrmRecordId; // Set the record ID

vtrmRecord.Status__c = 'Declined'; // Update the Status field to "Declined"

var result = sforce.connection.update([vtrmRecord]); // Update the record in Salesforce

if (result[0].success == 'true') {
    alert("Record successfully declined.");
    location.reload(); // Reload the page to reflect the changes
} else {
    alert("An error occurred while declining the record: " + result[0].errors.message);
}
